import heapq
from collections import Counter


def _dependency_solver(data, order, preference):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    rows = {name: {row["version"]: row for row in versions}
            for name, versions in packages.items()}
    choices = [[None] + list(rows[name]) for name in names]
    best_vector = None
    best_versions = None

    for values in product(*choices):
        installed = {name: version for name, version in zip(names, values)
                     if version is not None}
        if any(name not in installed or not low <= installed[name] <= high
               for name, (low, high) in data["roots"].items()):
            continue
        if any(name in installed and installed[name] != version
               for name, version in pins.items()):
            continue
        if any(version in blocked.get(name, []) for name, version in installed.items()):
            continue

        edges = {name: [] for name in installed}
        valid = True
        for name, version in installed.items():
            row = rows[name][version]
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                if other not in installed or not dep["min"] <= installed[other] <= dep["max"]:
                    valid = False
                    break
                edges[name].append(other)
            if not valid:
                break
        if not valid:
            continue

        reached = set()
        stack = list(data["roots"])
        while stack:
            name = stack.pop()
            if name in reached:
                continue
            reached.add(name)
            stack.extend(edges[name])
        if reached != set(installed):
            continue

        state, cyclic = {}, False
        def visit(name):
            nonlocal cyclic
            if state.get(name) == 1:
                cyclic = True
                return
            if state.get(name) == 2:
                return
            state[name] = 1
            for other in edges[name]:
                visit(other)
                if cyclic:
                    return
            state[name] = 2
        for name in installed:
            visit(name)
            if cyclic:
                break
        if cyclic:
            continue

        ordered = sorted(names, reverse=(order == "descending"))
        vector = tuple(installed.get(name, -1) for name in ordered)
        if (best_vector is None or
                (vector < best_vector if preference == "minimum" else vector > best_vector)):
            best_vector, best_versions = vector, installed

    return {"versions": best_versions} if best_versions is not None else {"error": "unsatisfiable"}


def _build_component_01():
    return lambda data: _dependency_solver(data, "descending", "minimum")


def _build_component_02():
    return lambda data: _dependency_solver(data, "ascending", "maximum")


def _build_component_03():
